{
  "component": {
    "definition_id": "launch-control-area-v1",
    "name": "Launch Control — Plan to Launch",
    "props": {},
    "source": "import React from 'react'

const STAGES = [
  { label: 'Plan', detail: 'Aligned', state: 'done' },
  { label: 'Scope', detail: 'Locked', state: 'done' },
  { label: 'Build', detail: 'In progress', state: 'active' },
  { label: 'Validate', detail: 'Next', state: 'queued' },
  { label: 'Launch', detail: 'Target', state: 'queued' },
]

function clampRisk(value: number) {
  return Math.max(0, Math.min(100, Math.round(value)))
}

export default function LaunchControl({
  interactionEnabled,
  state,
  setState,
}: {
  interactionEnabled: boolean
  state: Record<string, unknown>
  setState: (
    next:
      | Record<string, unknown>
      | ((current: Record<string, unknown>) => Record<string, unknown>)
  ) => void
}) {
  const risk = clampRisk(Number(state.risk ?? 42))
  const riskTone = risk < 35 ? '#2DD4BF' : risk < 70 ? '#FBBF24' : '#FB7185'
  const riskLabel = risk < 35 ? 'Low' : risk < 70 ? 'Watch' : 'High'

  const updateRisk = (next: number) => {
    setState((current) => ({ ...current, risk: clampRisk(next) }))
  }

  return (
    <main
      style={{
        width: '100%',
        height: '100%',
        boxSizing: 'border-box',
        borderRadius: 24,
        background:
          'linear-gradient(135deg, rgba(15,23,42,0.99) 0%, rgba(17,24,39,0.99) 58%, rgba(22,30,45,0.99) 100%)',
        border: '1px solid rgba(148,163,184,0.22)',
        boxShadow: '0 22px 54px rgba(15,23,42,0.26)',
        color: '#F8FAFC',
        fontFamily:
          'Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
        padding: '22px 24px',
        display: 'grid',
        gridTemplateColumns: '1fr 244px',
        gap: 24,
        overflow: 'hidden',
      }}
    >
      <section style={{ minWidth: 0, display: 'flex', flexDirection: 'column' }}>
        <header
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'flex-start',
            gap: 16,
          }}
        >
          <div>
            <div
              style={{
                color: '#5EEAD4',
                fontSize: 11,
                fontWeight: 800,
                letterSpacing: '0.16em',
                textTransform: 'uppercase',
              }}
            >
              Launch control
            </div>
            <h1
              style={{
                margin: '5px 0 0',
                fontSize: 24,
                lineHeight: 1.08,
                letterSpacing: '-0.035em',
              }}
            >
              Plan → Launch
            </h1>
          </div>
          <div
            style={{
              padding: '7px 10px',
              borderRadius: 999,
              background: 'rgba(45,212,191,0.12)',
              color: '#99F6E4',
              fontSize: 11,
              fontWeight: 750,
              whiteSpace: 'nowrap',
            }}
          >
            2 of 5 complete
          </div>
        </header>

        <div
          style={{
            marginTop: 24,
            display: 'grid',
            gridTemplateColumns: 'repeat(5, minmax(0, 1fr))',
            gap: 0,
          }}
        >
          {STAGES.map((stage, index) => {
            const done = stage.state === 'done'
            const active = stage.state === 'active'
            const color = done ? '#2DD4BF' : active ? '#FBBF24' : '#64748B'
            return (
              <div key={stage.label} style={{ position: 'relative', minWidth: 0 }}>
                {index < STAGES.length - 1 ? (
                  <div
                    style={{
                      position: 'absolute',
                      left: 28,
                      right: -4,
                      top: 11,
                      height: 2,
                      background: done
                        ? 'linear-gradient(90deg, #2DD4BF, #2DD4BF)'
                        : 'rgba(100,116,139,0.35)',
                    }}
                  />
                ) : null}
                <div
                  style={{
                    width: 24,
                    height: 24,
                    borderRadius: 999,
                    display: 'grid',
                    placeItems: 'center',
                    position: 'relative',
                    zIndex: 1,
                    boxSizing: 'border-box',
                    color: done ? '#062C2A' : '#0F172A',
                    background: color,
                    border: active ? '4px solid rgba(251,191,36,0.24)' : 'none',
                    boxShadow: active ? '0 0 0 2px #FBBF24' : 'none',
                    fontSize: 11,
                    fontWeight: 900,
                  }}
                >
                  {done ? '✓' : index + 1}
                </div>
                <div
                  style={{
                    marginTop: 10,
                    fontSize: 12,
                    fontWeight: 800,
                    color: active || done ? '#F8FAFC' : '#94A3B8',
                  }}
                >
                  {stage.label}
                </div>
                <div
                  style={{
                    marginTop: 3,
                    fontSize: 10,
                    color: active ? '#FDE68A' : '#64748B',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {stage.detail}
                </div>
              </div>
            )
          })}
        </div>

        <footer
          style={{
            marginTop: 'auto',
            paddingTop: 18,
            display: 'flex',
            alignItems: 'center',
            gap: 9,
            color: '#94A3B8',
            fontSize: 11,
          }}
        >
          <span
            style={{
              width: 7,
              height: 7,
              borderRadius: 999,
              background: '#FBBF24',
              boxShadow: '0 0 0 4px rgba(251,191,36,0.12)',
            }}
          />
          Build is the current launch gate
        </footer>
      </section>

      <aside
        style={{
          borderLeft: '1px solid rgba(148,163,184,0.18)',
          paddingLeft: 24,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
        }}
      >
        <div>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
            }}
          >
            <div
              style={{
                color: '#CBD5E1',
                fontSize: 11,
                fontWeight: 800,
                letterSpacing: '0.08em',
                textTransform: 'uppercase',
              }}
            >
              Launch risk
            </div>
            <div
              style={{
                borderRadius: 999,
                padding: '4px 8px',
                color: riskTone,
                background: `${riskTone}18`,
                fontSize: 10,
                fontWeight: 900,
              }}
            >
              {riskLabel}
            </div>
          </div>
          <div
            style={{
              marginTop: 8,
              display: 'flex',
              alignItems: 'baseline',
              gap: 6,
            }}
          >
            <strong style={{ fontSize: 40, letterSpacing: '-0.06em', color: riskTone }}>
              {risk}
            </strong>
            <span style={{ fontSize: 12, color: '#64748B' }}>/ 100</span>
          </div>
          <div
            style={{
              marginTop: 10,
              height: 7,
              borderRadius: 999,
              background: 'rgba(100,116,139,0.25)',
              overflow: 'hidden',
            }}
          >
            <div
              style={{
                width: `${risk}%`,
                height: '100%',
                borderRadius: 999,
                background: riskTone,
                transition: 'width 160ms ease, background 160ms ease',
              }}
            />
          </div>
          <input
            aria-label="Launch risk"
            type="range"
            min={0}
            max={100}
            step={5}
            value={risk}
            disabled={!interactionEnabled}
            onInput={(event) => updateRisk(Number(event.currentTarget.value))}
            onChange={(event) => updateRisk(Number(event.currentTarget.value))}
            style={{
              width: '100%',
              margin: '10px 0 0',
              accentColor: riskTone,
              opacity: interactionEnabled ? 1 : 0.48,
            }}
          />
        </div>

        <div
          style={{
            display: 'grid',
            gridTemplateColumns: '42px 1fr 42px',
            gap: 8,
            alignItems: 'center',
          }}
        >
          <button
            type="button"
            aria-label="Decrease launch risk"
            disabled={!interactionEnabled}
            onClick={() => updateRisk(risk - 5)}
            style={{
              height: 34,
              border: '1px solid rgba(148,163,184,0.26)',
              borderRadius: 10,
              background: 'rgba(30,41,59,0.84)',
              color: '#E2E8F0',
              fontSize: 19,
              cursor: interactionEnabled ? 'pointer' : 'default',
              opacity: interactionEnabled ? 1 : 0.45,
            }}
          >
            −
          </button>
          <div style={{ textAlign: 'center', color: '#64748B', fontSize: 10 }}>
            Adjust by 5
          </div>
          <button
            type="button"
            aria-label="Increase launch risk"
            disabled={!interactionEnabled}
            onClick={() => updateRisk(risk + 5)}
            style={{
              height: 34,
              border: '1px solid rgba(148,163,184,0.26)',
              borderRadius: 10,
              background: 'rgba(30,41,59,0.84)',
              color: '#E2E8F0',
              fontSize: 19,
              cursor: interactionEnabled ? 'pointer' : 'default',
              opacity: interactionEnabled ? 1 : 0.45,
            }}
          >
            +
          </button>
        </div>
      </aside>
    </main>
  )
}",
